import React, {
  useEffect,
  useState,
} from 'react';

import {
  toast,
} from 'react-toastify';

import {
  FiSettings,
  FiGlobe,
  FiPhone,
  FiMail,
  FiMapPin,
  FiFacebook,
  FiYoutube,
  FiImage,
  FiSave,
  FiMessageCircle,
  FiMap,
  FiUploadCloud,
  FiTrash2,
} from 'react-icons/fi';

import api from '../../services/api';
import AdminCard from '../common/AdminCard';
import { getImageUrl } from '../../utils/helpers';

import {
  useLanguage,
} from '../../contexts/LanguageContext';

// =====================================================

const initialSettings = {
  site_name_en: 'SC Academy',
  site_name_km: 'SC Academy',
  site_description_en: '',
  site_description_km: '',
  logo_url: '',
  favicon_url: '',
  address_en: '',
  address_km: '',
  phone: '',
  email: '',
  facebook_url: '',
  telegram_url: '',
  youtube_url: '',
  google_map_url: '',
};


// =====================================================
// ADMIN SETTINGS
// =====================================================

const AdminSettings = () => {

  // ===================================================
  // LANGUAGE
  // ===================================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';

  const siteNameField = isKhmer ? 'site_name_km' : 'site_name_en';
  const siteDescriptionField = isKhmer
    ? 'site_description_km'
    : 'site_description_en';
  const addressField = isKhmer ? 'address_km' : 'address_en';


  // ===================================================
  // TRANSLATION FALLBACK
  // ===================================================

  const tr = (
    key,
    english,
    khmer
  ) => {

    const value =
      t(key);


    if (
      value &&
      value !== key
    ) {

      return value;

    }


    return isKhmer
      ? khmer
      : english;

  };


  // ===================================================
  // STATE
  // ===================================================

  const [
    settings,
    setSettings,
  ] = useState({
    ...initialSettings,
  });



  const fetchSettings =
    async () => {

      try {

        setLoading(true);


        const response =
          await api.get(
            '/api/settings/'
          );


        const data =
          response.data;


        if (data) {

          setSettings({
            ...initialSettings,
            ...data,
          });

        } else {

          setSettings({
            ...initialSettings,
          });

        }

      } catch (error) {

        console.error(
          'Fetch settings error:',
          error
        );


        toast.error(
          error.response?.data?.detail ||
          tr(
            'settings.loadFailed',
            'Failed to load settings.',
            'មិនអាចផ្ទុកការកំណត់បានទេ។'
          ),
          { toastId: 'settings-load-error' }
        );

      } finally {

        setLoading(false);

      }

    };


  // ===================================================
  // INITIAL LOAD
  // ===================================================

  useEffect(() => {

    fetchSettings();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  // ===================================================
  // HANDLE CHANGE
  // ===================================================

  const handleChange = (
    field,
    value
  ) => {

    setSettings(
      (previous) => ({

        ...previous,

        [field]: value,

      })
    );

  };


  // ===================================================
  // SAVE SETTINGS
  // ===================================================

  const handleSubmit =
    async (e) => {

      e.preventDefault();


      try {

        setSaving(true);


        const payload = {

          site_name_en: settings.site_name_en || '',
          site_name_km: settings.site_name_km || '',
          site_description_en: settings.site_description_en || '',
          site_description_km: settings.site_description_km || '',

          logo_url:
            settings.logo_url ||
            '',

          favicon_url:
            settings.favicon_url ||
            '',

          address_en: settings.address_en || '',
          address_km: settings.address_km || '',

          phone:
            settings.phone ||
            '',

          email:
            settings.email ||
            '',

          facebook_url:
            settings.facebook_url ||
            '',

          telegram_url:
            settings.telegram_url ||
            '',

          youtube_url:
            settings.youtube_url ||
            '',

          google_map_url:
            settings.google_map_url ||
            '',

        };


        const response =
          await api.put(
            '/api/settings/',
            payload
          );


        if (
          response.data
        ) {

          setSettings(
            (previous) => ({

              ...previous,

              ...response.data,

            })
          );

        }


        toast.success(
          tr(
            'settings.updatedSuccess',
            'Settings updated successfully.',
            'បានកែប្រែការកំណត់ដោយជោគជ័យ។'
          )
        );

      } catch (error) {

        console.error(
          'Update settings error:',
          error
        );


        const detail =
          error.response?.data
            ?.detail;


        if (
          Array.isArray(detail)
        ) {

          toast.error(
            detail
              .map(
                (item) =>
                  item?.msg ||
                  tr(
                    'settings.updateFailed',
                    'Failed to update settings.',
                    'មិនអាចកែប្រែការកំណត់បានទេ។'
                  )
              )
              .join(', ')
          );

        } else {

          toast.error(
            detail ||
            tr(
              'settings.updateFailed',
              'Failed to update settings.',
              'មិនអាចកែប្រែការកំណត់បានទេ។'
            )
          );

        }

      } finally {

