                    "
                  >

                    {tr(
                      'settings.logoUrl',
                      'Logo URL',
                      'តំណ Logo'
                    )}

                  </label>


                  <input
                    type="url"

                    value={
                      settings.logo_url ||
                      ''
                    }

                    onChange={(e) =>
                      handleChange(
                        'logo_url',
                        e.target.value
                      )
                    }

                    className="
                      w-full
                      h-11

                      px-3.5

                      border
                      border-[#E8EEF9]

                      rounded-lg

                      bg-[#F0F7FF]

                      text-sm
                      text-[#0D1B3E]

                      placeholder:text-[#6B8AFF]

                      outline-none

                      focus:border-[#0D1B3E]
                      focus:bg-white
                      focus:ring-1
                      focus:ring-[#0D1B3E]

                      transition-all
                      duration-200
                    "

                    placeholder="https://example.com/logo.png"
                  />

                </div>


                {/* =======================================
                    FAVICON
                ======================================== */}

                <div>

                  <label
                    className="
                      block

                      text-sm
                      font-semibold
                      text-[#0D1B3E]

                      mb-1.5
                    "
                  >

                    {tr(
                      'settings.faviconUrl',
                      'Favicon URL',
                      'តំណ Favicon'
                    )}

                  </label>


                  <input
                    type="url"

                    value={
                      settings.favicon_url ||
                      ''
                    }

                    onChange={(e) =>
                      handleChange(
                        'favicon_url',
                        e.target.value
                      )
                    }

                    className="
                      w-full
                      h-11

                      px-3.5

                      border
                      border-[#E8EEF9]

                      rounded-lg

                      bg-[#F0F7FF]

                      text-sm
                      text-[#0D1B3E]

                      placeholder:text-[#6B8AFF]

                      outline-none

                      focus:border-[#0D1B3E]
                      focus:bg-white
                      focus:ring-1
                      focus:ring-[#0D1B3E]

                      transition-all
                      duration-200
                    "

                    placeholder="https://example.com/favicon.ico"
                  />

                </div>

              </div>

            </div>

          </AdminCard>


          {/* =============================================
              SAVE AREA
          ============================================== */}

          <div
            className="
              flex
              items-center
              justify-end

              pt-2
            "
          >

            <button
              type="submit"

              disabled={
                saving
              }

              className={`
                h-11

                inline-flex
                items-center
                justify-center
                gap-2

                px-6

                rounded-lg

                bg-[#C23636]
                hover:bg-[#A92E2E]

                text-white

                text-sm
                font-semibold

                shadow-sm

                transition-all
                duration-200

                ${
                  saving
                    ? `
                      opacity-60
                      cursor-not-allowed
                    `
                    : ''
                }
              `}
            >

              {
                saving ? (

                  <>

                    <span
                      className="
                        w-4
                        h-4

                        rounded-full

                        border-2
                        border-white/40
                        border-t-white

                        animate-spin
                      "
                    />


                    {tr(
                      'settings.saving',
                      'Saving...',
                      'កំពុងរក្សាទុក...'
                    )}

                  </>

                ) : (

                  <>

                    <FiSave
                      size={17}
                    />


                    {tr(
                      'settings.saveSettings',
                      'Save Settings',
                      'រក្សាទុកការកំណត់'
                    )}

                  </>

                )
              }

            </button>

          </div>

        </div>

      </form>

    </div>

  );

};


export default AdminSettings;
